// CRAG finance — comparison question 18dabb4f-d025-426c-9915-4c5995790f60
//
// Question (verbatim):
// which stock had higher gross income in the 4th quarter of 2023? apple or microsoft
//
// Replace the body below. Resolve company names via df.db.records, fetch
// finance data via df.tool.cragFinance.*, compute, then RETURN df.answer(...).

async function main() {
  const [appleMatches, msftMatches] = await Promise.all([
    df.db.records.search("Apple Inc"),
    df.db.records.search("Microsoft"),
  ]);

  const appleTicker = appleMatches[0]?.id;
  const msftTicker = msftMatches[0]?.id;

  const [appleInfo, msftInfo] = await Promise.all([
    df.tool.cragFinance.get_info({ ticker: appleTicker }),
    df.tool.cragFinance.get_info({ ticker: msftTicker }),
  ]);

  // get_info may include financials; log keys to understand structure
  const appleGross = appleInfo?.grossProfits ?? appleInfo?.grossProfit ?? null;
  const msftGross = msftInfo?.grossProfits ?? msftInfo?.grossProfit ?? null;

  // Q4 2023 for Apple = fiscal Q1 2024 (Oct-Dec 2023), MSFT fiscal Q2 2024
  // get_info typically returns TTM or latest annual; may not have quarterly breakdown
  // Try to find quarterly gross profit data in the info object
  const evidence = [
    { reason: `Apple (${appleTicker}) info keys: ${Object.keys(appleInfo || {}).join(", ")}` },
    { reason: `Apple grossProfits: ${appleGross}, MSFT grossProfits: ${msftGross}` },
    { reason: `MSFT (${msftTicker}) info keys: ${Object.keys(msftInfo || {}).join(", ")}` },
  ];

  if (appleGross !== null && msftGross !== null) {
    const winner = appleGross > msftGross ? "Apple" : "Microsoft";
    return df.answer({
      status: "answered",
      value: winner,
      evidence,
    });
  }

  // If gross profit not directly available, return unsupported
  return df.answer({
    status: "unsupported",
    value: null,
    evidence,
    reason: "Quarterly gross income data not available through get_info",
  });
}

return await main();

